style.css:
/* Image */
img {
    width: 100%; /* Make the image fill the width of its container */
    height: auto; /* Maintain aspect ratio */
}

/* Background color */
body {
    background-color: #F5F5F5; /* Light gray background */
}

/* Text */
h1 {
    font-family: Arial, sans-serif;
    font-size: 36px;
    color: #333;
    margin: 20px;
}

p {
    font-family: Arial, sans-serif;
    font-size: 18px;
    color: #666;
    margin: 10px;
}
